'use strict';

// SAM v2 strict-profile spec of one run's stateful core (src/core.ts + the
// run lookup in src/host.impl.ts). status 'absent' stands for "never started".

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const INITIAL_STATE = { status: 'absent', task0: 'absent', task1: 'absent', task2: 'absent' };

const IN_FLIGHT = ['queued', 'running', 'evicted'];
const FINAL_RUN = ['completed', 'failed', 'cancelled'];
const TASK_DOMAIN = [{ task: 0 }, { task: 1 }, { task: 2 }, { task: 3 }, { task: -1 }];
const TASK_SCHEMA = { task: { type: 'number' } };

const derive = (ts) => {
  if (ts[0] === ts[1] && ts[1] === ts[2]) return ts[0];
  if (ts.includes('failed')) return 'failed';
  if (ts.some((t) => IN_FLIGHT.includes(t))) return 'running';
  return 'cancelled';
};

const commitTasks = (next, ts) => {
  next.task0 = ts[0];
  next.task1 = ts[1];
  next.task2 = ts[2];
  next.status = derive(ts);
};

const taskMove = (from, to) => (model) => (proposal, { reject, next }) => {
  if (model.status === 'absent') return reject('no-such-run');
  if (FINAL_RUN.includes(model.status)) return reject('run-closed');
  const t = proposal.task;
  if (t !== 0 && t !== 1 && t !== 2) return reject('no-such-task');
  const ts = [model.task0, model.task1, model.task2];
  if (ts[t] !== from) return reject('illegal-move');
  ts[t] = to;
  commitTasks(next, ts);
};

const intent = (schema, domain) => ({ action: (data = {}) => ({ ...data }), schema, domain });

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      status: { type: 'string' },
      task0: { type: 'string' },
      task1: { type: 'string' },
      task2: { type: 'string' },
    },
    actions: {
      START: intent({}, [{}]),
      TASK_STARTED: intent(TASK_SCHEMA, TASK_DOMAIN),
      TASK_COMPLETED: intent(TASK_SCHEMA, TASK_DOMAIN),
      TASK_FAILED: intent(TASK_SCHEMA, TASK_DOMAIN),
      TASK_EVICTED: intent(TASK_SCHEMA, TASK_DOMAIN),
      TASK_REQUEUED: intent(TASK_SCHEMA, TASK_DOMAIN),
      CANCEL: intent({}, [{}]),
    },
    acceptors: {
      START: (model) => (proposal, { reject, next }) => {
        if (model.status !== 'absent') return reject('run-exists');
        next.status = 'queued';
        next.task0 = 'queued';
        next.task1 = 'queued';
        next.task2 = 'queued';
      },
      TASK_STARTED: taskMove('queued', 'running'),
      TASK_COMPLETED: taskMove('running', 'completed'),
      TASK_FAILED: taskMove('running', 'failed'),
      TASK_EVICTED: taskMove('running', 'evicted'),
      TASK_REQUEUED: taskMove('evicted', 'queued'),
      CANCEL: (model) => (proposal, { reject, next }) => {
        if (model.status === 'absent') return reject('no-such-run');
        if (FINAL_RUN.includes(model.status)) return reject('run-closed');
        const ts = [model.task0, model.task1, model.task2];
        if (!ts.some((t) => IN_FLIGHT.includes(t))) return reject('nothing-in-flight');
        commitTasks(next, ts.map((t) => (IN_FLIGHT.includes(t) ? 'cancelled' : t)));
      },
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
const init = () => { setState(INITIAL_STATE); };

const actions = {
  START: (data = {}) => intents.START(data),
  TASK_STARTED: (data = {}) => intents.TASK_STARTED(data),
  TASK_COMPLETED: (data = {}) => intents.TASK_COMPLETED(data),
  TASK_FAILED: (data = {}) => intents.TASK_FAILED(data),
  TASK_EVICTED: (data = {}) => intents.TASK_EVICTED(data),
  TASK_REQUEUED: (data = {}) => intents.TASK_REQUEUED(data),
  CANCEL: (data = {}) => intents.CANCEL(data),
};

module.exports = { instance, init, actions, getState, setState };

