// Rules the brief requires, independent of how the spec derives status.
const IN_FLIGHT = ['queued', 'running', 'evicted'];
const FINAL = ['completed', 'failed', 'cancelled'];
const tasks = (s) => [s.task0, s.task1, s.task2];
const same = (a, b) => ['status', 'task0', 'task1', 'task2'].every((k) => a[k] === b[k]);

const LEGAL_MOVES = {
  TASK_STARTED: ['queued', 'running'],
  TASK_COMPLETED: ['running', 'completed'],
  TASK_FAILED: ['running', 'failed'],
  TASK_EVICTED: ['running', 'evicted'],
  TASK_REQUEUED: ['evicted', 'queued'],
};

export const stateInvariants = [
  { name: 'absent-is-all-or-nothing', pred: (s) => (s.status === 'absent') === tasks(s).every((t) => t === 'absent') },
  { name: 'completed-only-when-all-completed', pred: (s) => s.status !== 'completed' || tasks(s).every((t) => t === 'completed') },
  { name: 'failed-whenever-a-task-failed', pred: (s) => !tasks(s).includes('failed') || s.status === 'failed' },
  { name: 'never-completed-or-cancelled-while-in-flight', pred: (s) =>
      !['completed', 'cancelled'].includes(s.status) || !tasks(s).some((t) => IN_FLIGHT.includes(t)) },
  { name: 'evicted-task-keeps-run-open', pred: (s) =>
      !tasks(s).includes('evicted') || ['running', 'evicted'].includes(s.status) },
  { name: 'uniform-tasks-give-that-status', pred: (s) => {
      const ts = tasks(s);
      return !(ts[0] === ts[1] && ts[1] === ts[2]) || s.status === ts[0];
    } },
