export function deriveStatus(tasks: readonly Status[]): Status {
  if (tasks.every((t) => t === tasks[0])) return tasks[0];
  if (tasks.some((t) => t === 'failed')) return 'failed';
  if (tasks.some(isInFlight)) return 'running';
  return 'cancelled';
}

export function initialRun(): RunState {
  return { status: 'queued', tasks: ['queued', 'queued', 'queued'] };
}

function closedReason(run: RunState): string | null {
  return FINAL_RUN.has(run.status) ? `run is ${run.status}` : null;
}

function settle(tasks: Tasks): RunState {
  return { status: deriveStatus(tasks), tasks };
}

export function applyTaskEvent(run: RunState, event: TaskEvent, task: unknown): StepResult {
  const closed = closedReason(run);
  if (closed) return { ok: false, reason: closed };
  if (task !== 0 && task !== 1 && task !== 2) return { ok: false, reason: 'no such task' };
  const move = MOVES[event];
  const current = run.tasks[task];
  if (current !== move.from) {
    return { ok: false, reason: `task ${task} is ${current}, not ${move.from}` };
  }
  const tasks: Tasks = [...run.tasks];
  tasks[task] = move.to;
  return { ok: true, state: settle(tasks) };
}

export function applyCancel(run: RunState): StepResult {
  const closed = closedReason(run);
  if (closed) return { ok: false, reason: closed };
  if (!run.tasks.some(isInFlight)) return { ok: false, reason: 'no task in flight' };
  const tasks = run.tasks.map((t) => (isInFlight(t) ? 'cancelled' : t)) as Tasks;
  return { ok: true, state: settle(tasks) };
}

import type { CreateHost, Host, Outcome, RunView } from '../host.ts';
import { applyCancel, applyTaskEvent, initialRun } from './core.ts';
import type { RunState, StepResult, TaskEvent } from './core.ts';

const refuse = (reason: string): Outcome => ({ ok: false, reason });

const createHost: CreateHost = async () => {
  const runs = new Map<string, RunState>();

  const commit = (id: string, step: (run: RunState) => StepResult): Outcome => {
    const run = runs.get(id);
    if (!run) return refuse(`no run ${JSON.stringify(id)}`);
    const result = step(run);
    if (!result.ok) return refuse(result.reason);
    runs.set(id, result.state);
    return { ok: true };
  };

  const report = (event: TaskEvent) => async (id: string, task: number): Promise<Outcome> =>
    commit(id, (run) => applyTaskEvent(run, event, task));

  const host: Host = {
    async start(id) {
      if (runs.has(id)) return refuse(`run ${JSON.stringify(id)} exists`);
      runs.set(id, initialRun());
      return { ok: true };
    },
    taskStarted: report('taskStarted'),
    taskCompleted: report('taskCompleted'),
    taskFailed: report('taskFailed'),
    taskEvicted: report('taskEvicted'),
    taskRequeued: report('taskRequeued'),
    async cancel(id) {
      return commit(id, applyCancel);
    },
    async run(id): Promise<RunView | null> {
      const run = runs.get(id);
      if (!run) return null;
      return { status: run.status, task0: run.tasks[0], task1: run.tasks[1], task2: run.tasks[2] };
    },
  };
  return host;
};

export default createHost;

