import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('start, unknown run, duplicate', async () => {
  const h = await createHost();
  assert.equal(await h.run('a'), null);
  assert.equal((await h.taskStarted('a', 0)).ok, false);
  assert.equal((await h.cancel('a')).ok, false);
  assert.deepEqual(await h.start('a'), { ok: true });
  assert.equal((await h.start('a')).ok, false);
  assert.deepEqual(await h.run('a'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued' });
});

test('happy path to completed, then everything refused', async () => {
  const h = await createHost();
  await h.start('r');
  for (const t of [0, 1, 2]) assert.equal((await h.taskStarted('r', t)).ok, true);
  assert.equal((await h.run('r'))!.status, 'running');
  await h.taskCompleted('r', 0);
  await h.taskCompleted('r', 1);
  assert.equal((await h.run('r'))!.status, 'running');
  await h.taskCompleted('r', 2);
  assert.equal((await h.run('r'))!.status, 'completed');
  assert.equal((await h.cancel('r')).ok, false);
  assert.equal((await h.start('r')).ok, false);
});

test('bad moves and bad task numbers refused', async () => {
  const h = await createHost();
  await h.start('r');
  for (const t of [-1, 3, 1.5, NaN]) assert.equal((await h.taskStarted('r', t)).ok, false);
  assert.equal((await h.taskCompleted('r', 0)).ok, false);
  assert.equal((await h.taskRequeued('r', 0)).ok, false);
  assert.deepEqual(await h.run('r'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued' });
});

test('eviction keeps run in flight; all evicted shows evicted', async () => {
  const h = await createHost();
  await h.start('r');
  for (const t of [0, 1, 2]) { await h.taskStarted('r', t); await h.taskEvicted('r', t); }
  assert.equal((await h.run('r'))!.status, 'evicted');
  await h.taskRequeued('r', 0);
  assert.equal((await h.run('r'))!.status, 'running');
});

test('failure fails the run and closes it', async () => {
  const h = await createHost();
  await h.start('r');
  await h.taskStarted('r', 1);
  await h.taskFailed('r', 1);
  assert.deepEqual(await h.run('r'), { status: 'failed', task0: 'queued', task1: 'failed', task2: 'queued' });
  assert.equal((await h.taskStarted('r', 0)).ok, false);
});

test('cancel', async () => {
  const h = await createHost();
  await h.start('r');
  await h.taskStarted('r', 0);
  await h.taskCompleted('r', 0);
  assert.equal((await h.cancel('r')).ok, true);
  assert.deepEqual(await h.run('r'), { status: 'cancelled', task0: 'completed', task1: 'cancelled', task2: 'cancelled' });
  assert.equal((await h.cancel('r')).ok, false);
});

'use strict';

// SAM v2 strict-profile spec of one run's stateful core (src/core.ts + the
// run lookup in src/host.impl.ts). status 'absent' stands for "never started".

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const INITIAL_STATE = { status: 'absent', task0: 'absent', task1: 'absent', task2: 'absent' };

const IN_FLIGHT = ['queued', 'running', 'evicted'];
const FINAL_RUN = ['completed', 'failed', 'cancelled'];
const TASK_DOMAIN = [{ task: 0 }, { task: 1 }, { task: 2 }, { task: 3 }, { task: -1 }];
const TASK_SCHEMA = { task: { type: 'number' } };

const derive = (ts) => {
  if (ts[0] === ts[1] && ts[1] === ts[2]) return ts[0];
  if (ts.includes('failed')) return 'failed';
  if (ts.some((t) => IN_FLIGHT.includes(t))) return 'running';
  return 'cancelled';
};

const commitTasks = (next, ts) => {
  next.task0 = ts[0];
  next.task1 = ts[1];
  next.task2 = ts[2];
  next.status = derive(ts);
};

const taskMove = (from, to) => (model) => (proposal, { reject, next }) => {
  if (model.status === 'absent') return reject('no-such-run');
  if (FINAL_RUN.includes(model.status)) return reject('closed-run-refuses-all');
  const t = proposal.task;
  if (t !== 0 && t !== 1 && t !== 2) return reject('no-such-task');
  const ts = [model.task0, model.task1, model.task2];
  if (ts[t] !== from) return reject('illegal-move');
  ts[t] = to;
  commitTasks(next, ts);
};

const intent = (schema, domain) => ({ action: (data = {}) => ({ ...data }), schema, domain });

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      status: { type: 'string' },
      task0: { type: 'string' },
      task1: { type: 'string' },
      task2: { type: 'string' },
    },
    actions: {
      START: intent({}, [{}]),
      TASK_STARTED: intent(TASK_SCHEMA, TASK_DOMAIN),
      TASK_COMPLETED: intent(TASK_SCHEMA, TASK_DOMAIN),
      TASK_FAILED: intent(TASK_SCHEMA, TASK_DOMAIN),
      TASK_EVICTED: intent(TASK_SCHEMA, TASK_DOMAIN),
      TASK_REQUEUED: intent(TASK_SCHEMA, TASK_DOMAIN),
      CANCEL: intent({}, [{}]),
    },
    acceptors: {
      START: (model) => (proposal, { reject, next }) => {
        if (model.status !== 'absent') return reject('run-exists');
        next.status = 'queued';
        next.task0 = 'queued';
        next.task1 = 'queued';
        next.task2 = 'queued';
      },
      TASK_STARTED: taskMove('queued', 'running'),
      TASK_COMPLETED: taskMove('running', 'completed'),
      TASK_FAILED: taskMove('running', 'failed'),
      TASK_EVICTED: taskMove('running', 'evicted'),
      TASK_REQUEUED: taskMove('evicted', 'queued'),
      CANCEL: (model) => (proposal, { reject, next }) => {
        if (model.status === 'absent') return reject('no-such-run');
        if (FINAL_RUN.includes(model.status)) return reject('closed-run-refuses-all');
        const ts = [model.task0, model.task1, model.task2];
        if (!ts.some((t) => IN_FLIGHT.includes(t))) return reject('cancel-needs-in-flight');
        commitTasks(next, ts.map((t) => (IN_FLIGHT.includes(t) ? 'cancelled' : t)));
      },
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
const init = () => { setState(INITIAL_STATE); };

const actions = {
  START: (data = {}) => intents.START(data),
  TASK_STARTED: (data = {}) => intents.TASK_STARTED(data),
  TASK_COMPLETED: (data = {}) => intents.TASK_COMPLETED(data),
  TASK_FAILED: (data = {}) => intents.TASK_FAILED(data),
  TASK_EVICTED: (data = {}) => intents.TASK_EVICTED(data),
  TASK_REQUEUED: (data = {}) => intents.TASK_REQUEUED(data),
  CANCEL: (data = {}) => intents.CANCEL(data),
};

module.exports = { instance, init, actions, getState, setState };

