test('cancelTask cancels one in-flight task and rederives status', async () => {
  const h = await createHost();
  assert.equal((await h.cancelTask('r', 0)).ok, false);
  await h.start('r');
  for (const t of [-1, 3, 0.5]) assert.equal((await h.cancelTask('r', t)).ok, false);
  assert.equal((await h.cancelTask('r', 0)).ok, true);
  assert.deepEqual(await h.run('r'), { status: 'running', task0: 'cancelled', task1: 'queued', task2: 'queued' });
  assert.equal((await h.cancelTask('r', 0)).ok, false);
  await h.taskStarted('r', 1);
  await h.taskEvicted('r', 1);
  assert.equal((await h.cancelTask('r', 1)).ok, true);
  await h.taskStarted('r', 2);
  assert.equal((await h.run('r'))!.status, 'running');
  assert.equal((await h.cancelTask('r', 2)).ok, true);
  assert.deepEqual(await h.run('r'), { status: 'cancelled', task0: 'cancelled', task1: 'cancelled', task2: 'cancelled' });
  assert.equal((await h.taskRetried('r', 2)).ok, false);
});

test('cancelTask: completed and failed tasks are final; failed run stays failed', async () => {
  const h = await createHost();
  await h.start('r');
  await h.taskStarted('r', 0);
  await h.taskCompleted('r', 0);
  assert.equal((await h.cancelTask('r', 0)).ok, false);
  await h.taskStarted('r', 1);
  await h.taskFailed('r', 1);
