// Rules the brief requires, independent of how the spec derives status.
const IN_FLIGHT = ['queued', 'running', 'evicted'];
// Run statuses that refuse every command; a failed run stays open for retries.
const CLOSED = ['completed', 'cancelled'];
const tasks = (s) => [s.task0, s.task1, s.task2];
const same = (a, b) => ['status', 'task0', 'task1', 'task2'].every((k) => a[k] === b[k]);

const LEGAL_MOVES = {
  TASK_STARTED: ['queued', 'running'],
  TASK_COMPLETED: ['running', 'completed'],
  TASK_FAILED: ['running', 'failed'],
  TASK_EVICTED: ['running', 'evicted'],
  TASK_REQUEUED: ['evicted', 'queued'],
  TASK_RETRIED: ['failed', 'queued'],
};

export const stateInvariants = [
  { name: 'absent-is-all-or-nothing', pred: (s) => (s.status === 'absent') === tasks(s).every((t) => t === 'absent') },
  { name: 'completed-only-when-all-completed', pred: (s) => s.status !== 'completed' || tasks(s).every((t) => t === 'completed') },
  { name: 'failed-whenever-a-task-failed', pred: (s) => !tasks(s).includes('failed') || s.status === 'failed' },
  { name: 'never-completed-or-cancelled-while-in-flight', pred: (s) =>
      !['completed', 'cancelled'].includes(s.status) || !tasks(s).some((t) => IN_FLIGHT.includes(t)) },
  // An evicted task is in flight: the run may be failed (a failure wins), but
  // never shown as finished-successfully, cancelled, or not-yet-started.
  { name: 'evicted-task-never-hidden', pred: (s) =>
      !tasks(s).includes('evicted') || ['running', 'evicted', 'failed'].includes(s.status) },
  { name: 'uniform-tasks-give-that-status', pred: (s) => {
      const ts = tasks(s);
      return !(ts[0] === ts[1] && ts[1] === ts[2]) || s.status === ts[0];
    } },
];

export const transitionInvariants = [
  { name: 'closed-run-never-changes', pred: (pre, _a, _d, post) => !CLOSED.includes(pre.status) || same(pre, post) },
  { name: 'failed-run-can-retry', pred: (pre, a, d, post) =>
      !(a === 'TASK_RETRIED' && pre.status === 'failed' && pre[`task${d.task}`] === 'failed') ||
      post[`task${d.task}`] === 'queued' },
  { name: 'unknown-run-only-start', pred: (pre, a, _d, post) => pre.status !== 'absent' || a === 'START' || same(pre, post) },
  { name: 'start-only-once', pred: (pre, a, _d, post) => a !== 'START' || pre.status === 'absent' || same(pre, post) },
  { name: 'bad-task-number-refused', pred: (pre, a, d, post) =>
      !(a in LEGAL_MOVES) || [0, 1, 2].includes(d.task) || same(pre, post) },
  { name: 'task-report-moves-one-task-legally', pred: (pre, a, d, post) => {
      if (!(a in LEGAL_MOVES) || same(pre, post)) return true;
      const [from, to] = LEGAL_MOVES[a];
      const k = `task${d.task}`;
      return pre[k] === from && post[k] === to &&
        ['task0', 'task1', 'task2'].every((o) => o === k || pre[o] === post[o]);
    } },
  { name: 'cancel-cancels-exactly-in-flight', pred: (pre, a, _d, post) => {
      if (a !== 'CANCEL' || same(pre, post)) return true;
      return ['task0', 'task1', 'task2'].every((k) =>
        IN_FLIGHT.includes(pre[k]) ? post[k] === 'cancelled' : post[k] === pre[k]);
    } },
  { name: 'cancel-refused-without-in-flight', pred: (pre, a, _d, post) =>
      a !== 'CANCEL' || tasks(pre).some((t) => IN_FLIGHT.includes(t)) || same(pre, post) },
];

// Drives the real host and records one NDJSON window per command into
// spec/traces/, in the contract's vocabulary. Deterministic (seeded walks).
import { mkdirSync, rmSync, writeFileSync } from 'node:fs';
import createHost from '../src/host.impl.ts';
import type { Host, RunView } from '../host.ts';

const OUT = new URL('./traces/', import.meta.url);
const ABSENT = { status: 'absent', task0: 'absent', task1: 'absent', task2: 'absent' };
const TASKS = [0, 1, 2, 3, -1];
const ACTIONS = ['START', 'TASK_STARTED', 'TASK_COMPLETED', 'TASK_FAILED', 'TASK_EVICTED', 'TASK_REQUEUED', 'TASK_RETRIED', 'CANCEL'];

const observe = async (h: Host): Promise<RunView | typeof ABSENT> => (await h.run('r')) ?? ABSENT;

const invoke = (h: Host, action: string, task: number) => {
  switch (action) {
    case 'START': return h.start('r');
    case 'TASK_STARTED': return h.taskStarted('r', task);
    case 'TASK_COMPLETED': return h.taskCompleted('r', task);
    case 'TASK_FAILED': return h.taskFailed('r', task);
    case 'TASK_EVICTED': return h.taskEvicted('r', task);
    case 'TASK_REQUEUED': return h.taskRequeued('r', task);
    case 'TASK_RETRIED': return h.taskRetried('r', task);
    default: return h.cancel('r');
  }
};

let seed = 12345;
// High bits only: the low bits of a power-of-two LCG cycle with a tiny period.
const rand = (n: number) => { seed = (seed * 1103515245 + 12345) % 2147483648; return Math.floor((seed / 2147483648) * n); };

rmSync(OUT, { recursive: true, force: true });
mkdirSync(OUT, { recursive: true });
for (let walk = 0; walk < 200; walk++) {
  const h = await createHost();
  const lines: string[] = [];
  for (let i = 0; i < 25; i++) {
    // Bias toward legal-looking task numbers so deep states get visited.
    // START and CANCEL are rare after the first step: CANCEL closes most runs.
    const roll = rand(100);
    const action = i === 0 && walk % 10 !== 0 ? 'START'
      : roll < 3 ? 'CANCEL' : roll < 5 ? 'START' : ACTIONS[1 + rand(ACTIONS.length - 2)];
    const task = TASKS[rand(10) < 9 ? rand(3) : 3 + rand(2)];
    const pre = await observe(h);
    await invoke(h, action, task);
    const post = await observe(h);
    const data = action === 'START' || action === 'CANCEL' ? {} : { task };
    lines.push(JSON.stringify({ pre, action, data, post }));
  }
  writeFileSync(new URL(`walk-${String(walk).padStart(3, '0')}.ndjson`, OUT), lines.join('\n') + '\n');
}

