import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('start, unknown run, duplicate', async () => {
  const h = await createHost();
  assert.equal(await h.run('a'), null);
  assert.equal((await h.taskStarted('a', 0)).ok, false);
  assert.equal((await h.cancel('a')).ok, false);
  assert.deepEqual(await h.start('a'), { ok: true });
  assert.equal((await h.start('a')).ok, false);
  assert.deepEqual(await h.run('a'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued' });
});

test('happy path to completed, then everything refused', async () => {
  const h = await createHost();
  await h.start('r');
  for (const t of [0, 1, 2]) assert.equal((await h.taskStarted('r', t)).ok, true);
  assert.equal((await h.run('r'))!.status, 'running');
  await h.taskCompleted('r', 0);
  await h.taskCompleted('r', 1);
  assert.equal((await h.run('r'))!.status, 'running');
  await h.taskCompleted('r', 2);
  assert.equal((await h.run('r'))!.status, 'completed');
  assert.equal((await h.cancel('r')).ok, false);
  assert.equal((await h.start('r')).ok, false);
});

test('bad moves and bad task numbers refused', async () => {
  const h = await createHost();
  await h.start('r');
  for (const t of [-1, 3, 1.5, NaN]) assert.equal((await h.taskStarted('r', t)).ok, false);
  assert.equal((await h.taskCompleted('r', 0)).ok, false);
  assert.equal((await h.taskRequeued('r', 0)).ok, false);
  assert.deepEqual(await h.run('r'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued' });
});

test('eviction keeps run in flight; all evicted shows evicted', async () => {
  const h = await createHost();
  await h.start('r');
  for (const t of [0, 1, 2]) { await h.taskStarted('r', t); await h.taskEvicted('r', t); }
  assert.equal((await h.run('r'))!.status, 'evicted');
  await h.taskRequeued('r', 0);
  assert.equal((await h.run('r'))!.status, 'running');
});

test('failure fails the run but it still accepts commands; retry requeues', async () => {
  const h = await createHost();
  await h.start('r');
  await h.taskStarted('r', 1);
  assert.equal((await h.taskRetried('r', 1)).ok, false);
  await h.taskFailed('r', 1);
  assert.deepEqual(await h.run('r'), { status: 'failed', task0: 'queued', task1: 'failed', task2: 'queued' });
  assert.equal((await h.taskStarted('r', 0)).ok, true);
  assert.equal((await h.run('r'))!.status, 'failed');
  assert.equal((await h.taskRetried('r', 0)).ok, false);
  assert.equal((await h.taskRetried('r', 3)).ok, false);
  assert.equal((await h.taskRetried('r', 1)).ok, true);
  assert.deepEqual(await h.run('r'), { status: 'running', task0: 'running', task1: 'queued', task2: 'queued' });
});

test('all failed, then retried to completion', async () => {
  const h = await createHost();
  await h.start('r');
  for (const t of [0, 1, 2]) { await h.taskStarted('r', t); await h.taskFailed('r', t); }
  assert.equal((await h.run('r'))!.status, 'failed');
  assert.equal((await h.cancel('r')).ok, false);
  for (const t of [0, 1, 2]) {
    assert.equal((await h.taskRetried('r', t)).ok, true);
    await h.taskStarted('r', t);
    await h.taskCompleted('r', t);
  }
  assert.deepEqual(await h.run('r'), { status: 'completed', task0: 'completed', task1: 'completed', task2: 'completed' });
  assert.equal((await h.taskRetried('r', 0)).ok, false);
});

test('cancelTask cancels one in-flight task and rederives status', async () => {
  const h = await createHost();
  assert.equal((await h.cancelTask('r', 0)).ok, false);
  await h.start('r');
  for (const t of [-1, 3, 0.5]) assert.equal((await h.cancelTask('r', t)).ok, false);
  assert.equal((await h.cancelTask('r', 0)).ok, true);
  assert.deepEqual(await h.run('r'), { status: 'running', task0: 'cancelled', task1: 'queued', task2: 'queued' });
  assert.equal((await h.cancelTask('r', 0)).ok, false);
  await h.taskStarted('r', 1);
  await h.taskEvicted('r', 1);
  assert.equal((await h.cancelTask('r', 1)).ok, true);
  await h.taskStarted('r', 2);
  assert.equal((await h.run('r'))!.status, 'running');
  assert.equal((await h.cancelTask('r', 2)).ok, true);
  assert.deepEqual(await h.run('r'), { status: 'cancelled', task0: 'cancelled', task1: 'cancelled', task2: 'cancelled' });
  assert.equal((await h.taskRetried('r', 2)).ok, false);
});

test('cancelTask: completed and failed tasks are final; failed run stays failed', async () => {
  const h = await createHost();
  await h.start('r');
  await h.taskStarted('r', 0);
  await h.taskCompleted('r', 0);
  assert.equal((await h.cancelTask('r', 0)).ok, false);
  await h.taskStarted('r', 1);
  await h.taskFailed('r', 1);
  assert.equal((await h.cancelTask('r', 1)).ok, false);
  assert.equal((await h.cancelTask('r', 2)).ok, true);
  assert.deepEqual(await h.run('r'), { status: 'failed', task0: 'completed', task1: 'failed', task2: 'cancelled' });
});

test('cancelTask of the last in-flight task beside completed ones cancels the run', async () => {
  const h = await createHost();
  await h.start('r');
  for (const t of [0, 1]) { await h.taskStarted('r', t); await h.taskCompleted('r', t); }
  await h.taskStarted('r', 2);
  assert.equal((await h.cancelTask('r', 2)).ok, true);
  assert.deepEqual(await h.run('r'), { status: 'cancelled', task0: 'completed', task1: 'completed', task2: 'cancelled' });
  assert.equal((await h.cancel('r')).ok, false);
});

test('cancel on a failed run keeps it failed, and the failed task can be retried', async () => {
  const h = await createHost();
  await h.start('r');
  await h.taskStarted('r', 0);
  await h.taskFailed('r', 0);
  assert.equal((await h.cancel('r')).ok, true);
  assert.deepEqual(await h.run('r'), { status: 'failed', task0: 'failed', task1: 'cancelled', task2: 'cancelled' });
  assert.equal((await h.taskRetried('r', 0)).ok, true);
  assert.deepEqual(await h.run('r'), { status: 'running', task0: 'queued', task1: 'cancelled', task2: 'cancelled' });
});

test('cancel', async () => {
  const h = await createHost();
  await h.start('r');
  await h.taskStarted('r', 0);
  await h.taskCompleted('r', 0);
  assert.equal((await h.cancel('r')).ok, true);
  assert.deepEqual(await h.run('r'), { status: 'cancelled', task0: 'completed', task1: 'cancelled', task2: 'cancelled' });
  assert.equal((await h.cancel('r')).ok, false);
});

