3	// SAM v2 strict-profile spec of one run's stateful core (src/core.ts + the
4	// run lookup in src/host.impl.ts). status 'absent' stands for "never started".
5	
6	const { createInstance } = require('@cognitive-fab/sam-pattern');
7	
8	const instance = createInstance({ strict: true, hasAsyncActions: false });
9	
10	const INITIAL_STATE = { status: 'absent', task0: 'absent', task1: 'absent', task2: 'absent' };
11	
12	const IN_FLIGHT = ['queued', 'running', 'evicted'];
13	const CLOSED_RUN = ['completed', 'cancelled'];
14	const TASK_DOMAIN = [{ task: 0 }, { task: 1 }, { task: 2 }, { task: 3 }, { task: -1 }];
15	const TASK_SCHEMA = { task: { type: 'number' } };
16	
17	const derive = (ts) => {
18	  if (ts[0] === ts[1] && ts[1] === ts[2]) return ts[0];
19	  if (ts.includes('failed')) return 'failed';
20	  if (ts.some((t) => IN_FLIGHT.includes(t))) return 'running';
21	  return 'cancelled';
22	};
23	
24	const commitTasks = (next, ts) => {
25	  next.task0 = ts[0];
26	  next.task1 = ts[1];
27	  next.task2 = ts[2];
28	  next.status = derive(ts);
