// Drives the real host and records one NDJSON window per command into
// spec/traces/, in the contract's vocabulary. Deterministic (seeded walks).
import { mkdirSync, rmSync, writeFileSync } from 'node:fs';
import createHost from '../src/host.impl.ts';
import type { Host, RunView } from '../host.ts';

const OUT = new URL('./traces/', import.meta.url);
const ABSENT = { status: 'absent', task0: 'absent', task1: 'absent', task2: 'absent' };
const TASKS = [0, 1, 2, 3, -1];
const ACTIONS = ['START', 'TASK_STARTED', 'TASK_COMPLETED', 'TASK_FAILED', 'TASK_EVICTED', 'TASK_REQUEUED', 'TASK_RETRIED', 'CANCEL_TASK', 'CANCEL'];

const observe = async (h: Host): Promise<RunView | typeof ABSENT> => (await h.run('r')) ?? ABSENT;

const invoke = (h: Host, action: string, task: number) => {
  switch (action) {
    case 'START': return h.start('r');
    case 'TASK_STARTED': return h.taskStarted('r', task);
    case 'TASK_COMPLETED': return h.taskCompleted('r', task);
    case 'TASK_FAILED': return h.taskFailed('r', task);
    case 'TASK_EVICTED': return h.taskEvicted('r', task);
    case 'TASK_REQUEUED': return h.taskRequeued('r', task);
    case 'TASK_RETRIED': return h.taskRetried('r', task);
    case 'CANCEL_TASK': return h.cancelTask('r', task);
    default: return h.cancel('r');
  }
};

let seed = 12345;
// High bits only: the low bits of a power-of-two LCG cycle with a tiny period.
const rand = (n: number) => { seed = (seed * 1103515245 + 12345) % 2147483648; return Math.floor((seed / 2147483648) * n); };

rmSync(OUT, { recursive: true, force: true });
mkdirSync(OUT, { recursive: true });
for (let walk = 0; walk < 200; walk++) {
  const h = await createHost();
  const lines: string[] = [];
  for (let i = 0; i < 25; i++) {
    // Bias toward legal-looking task numbers so deep states get visited.
    // START and CANCEL are rare after the first step: CANCEL closes most runs.
    const roll = rand(100);
    const action = i === 0 && walk % 10 !== 0 ? 'START'
      : roll < 3 ? 'CANCEL' : roll < 5 ? 'START' : ACTIONS[1 + rand(ACTIONS.length - 2)];
    const task = TASKS[rand(10) < 9 ? rand(3) : 3 + rand(2)];
    const pre = await observe(h);
    await invoke(h, action, task);
    const post = await observe(h);
    const data = action === 'START' || action === 'CANCEL' ? {} : { task };
    lines.push(JSON.stringify({ pre, action, data, post }));
  }
  writeFileSync(new URL(`walk-${String(walk).padStart(3, '0')}.ndjson`, OUT), lines.join('\n') + '\n');
}

